import{_ as o,C as r,c as s,o as i,a3 as t,G as a}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Manage payments","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/payments/manage-payments.md","filePath":"master/finance/payments/manage-payments.md","lastUpdated":1791902625000}'),l={name:"master/finance/payments/manage-payments.md"};function m(h,e,c,g,d,p){const n=r("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="manage-payments" tabindex="-1">Manage payments <a class="header-anchor" href="#manage-payments" aria-label="Permalink to &quot;Manage payments&quot;">​</a></h1><p>The payments list shows every payment you received or sent. You can open one, follow its status, confirm it, cancel it, or create a payment by hand. Most payments are made from an invoice with <strong>Pay</strong>, but a manual payment helps when no invoice exists yet, for example an advance.</p><blockquote><p><strong>In simple words:</strong> The Payments page is your cash diary. Each row is one payment, and the status tells you how far it has come.</p></blockquote><h2 id="where-to-find-payments" tabindex="-1">Where to find payments <a class="header-anchor" href="#where-to-find-payments" aria-label="Permalink to &quot;Where to find payments&quot;">​</a></h2><ul><li>Customer payments: <code>Invoices → Customers → Payments</code> or <code>Accounting → Customers → Payments</code>.</li><li>Vendor payments: <code>Invoices → Vendors → Payments</code> or <code>Accounting → Vendors → Payments</code>.</li></ul><p>Both apps show the same payments. Customer payments have the type <strong>Receive</strong>. Vendor payments have the type <strong>Send</strong>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2>',7)),a(n,{src:"/images1/finance/payments_list.png",alt:"Payments list with the views Default, Customer Payments, Vendor Payments, Draft, In Process, showing the Deco Addict payment of 891.25"}),e[1]||(e[1]=t('<h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><ul><li><strong><em>Date:</em></strong> The payment date.</li><li><strong><em>Name:</em></strong> The payment number, for example <code>PBANK/2026/1</code>. The prefix comes from the journal.</li><li><strong><em>Journal:</em></strong> The journal that holds the money, for example <strong>Bank Transactions</strong>.</li><li><strong><em>Payment Method:</em></strong> For example <strong>Manual Payment</strong>.</li><li><strong><em>Partner:</em></strong> The customer or vendor.</li><li><strong><em>Amount (Currency):</em></strong> The amount with a sign. A vendor payment shows a minus, for example -$34,040.00.</li><li><strong><em>Amount:</em></strong> The amount without a sign.</li><li><strong><em>State:</em></strong> The status of the payment.</li><li><strong><em>Company:</em></strong> Hidden by default. Turn it on from the column toggle.</li></ul><h3 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;Views&quot;">​</a></h3><p>The tabs above the list are saved filters.</p><ul><li><strong><em>Customer Payments:</em></strong> Only payments from customers.</li><li><strong><em>Vendor Payments:</em></strong> Only payments to vendors.</li><li><strong><em>Draft:</em></strong> Payments that are not confirmed yet.</li><li><strong><em>In Process:</em></strong> Confirmed payments.</li><li>More views are in the view menu: <strong>Sent</strong>, <strong>No Sent</strong>, <strong>No Bank Matching</strong> and <strong>Reconciled</strong>.</li></ul><h3 id="search-group-and-filter" tabindex="-1">Search, group and filter <a class="header-anchor" href="#search-group-and-filter" aria-label="Permalink to &quot;Search, group and filter&quot;">​</a></h3><ul><li>Use the search box to find a payment by name.</li><li>Click <strong>Group by</strong> to group by <strong>Name</strong>, <strong>Company</strong>, <strong>Journal</strong>, <strong>Payment Method Line</strong>, <strong>Partner</strong>, <strong>Payment Method</strong>, <strong>Partner Bank Account</strong>, <strong>Created At</strong> or <strong>Updated At</strong>.</li><li>Click the filter button to filter by journal, company, bank account, payment method, currency, partner or dates.</li></ul><p>See <a href="./../../getting-started/search-filter-group.html">Search, filter and group records</a>.</p><h3 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h3><p>Click <strong>Export</strong> above the list to download the payments. Pick the columns you need.</p><h2 id="create-a-payment-by-hand" tabindex="-1">Create a payment by hand <a class="header-anchor" href="#create-a-payment-by-hand" aria-label="Permalink to &quot;Create a payment by hand&quot;">​</a></h2><ol><li>Open the payments list and click <strong>New Payment</strong>.</li><li>Fill in the form.</li><li>Click <strong>Create</strong>.</li></ol>',12)),a(n,{src:"/images1/finance/payment_form.png",alt:"The New Payment form with Payment Type Receive, Customer Deco Addict, Amount 891.25, Currency USD, Date, Journal Bank Transactions, Payment Method Man"}),e[2]||(e[2]=t('<p>The form has a status bar at the top. A new payment starts as <strong>Draft</strong>.</p><h3 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h3><ul><li><strong><em>Payment Type:</em></strong> <strong>Receive</strong> for money in, <strong>Send</strong> for money out. The label of the partner field follows this choice.</li><li><strong><em>Customer</em></strong> or <strong><em>Vendor:</em></strong> The partner who pays or is paid. Choosing a partner fills the bank account and the method if they are known.</li><li><strong><em>Amount:</em></strong> The money moved. It must be zero or more.</li><li><strong><em>Currency:</em></strong> Starts with your company currency.</li><li><strong><em>Date:</em></strong> Starts as today.</li><li><strong><em>Memo:</em></strong> A free note, up to 255 characters. Use the invoice number or a bank reference.</li><li><strong><em>Journal:</em></strong> A bank, cash or credit card journal. Aureus picks the first one.</li><li><strong><em>Payment Method:</em></strong> The list depends on the journal and on the payment type.</li><li><strong><em>Customer Bank Account</em></strong> or <strong><em>Vendor Bank Account:</em></strong> The partner bank account. It shows only for the method <strong>Manual Payment</strong> on a non-cash journal. Pick from the accounts of the chosen partner. See <a href="./bank-accounts.html">Bank accounts</a>.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>A payment is editable only while it is a <strong>Draft</strong>. After you confirm it, the form is read only.</p></div><h2 id="statuses" tabindex="-1">Statuses <a class="header-anchor" href="#statuses" aria-label="Permalink to &quot;Statuses&quot;">​</a></h2><p>The status bar shows these steps:</p><ol><li><strong>Draft:</strong> Just created.</li><li><strong>In Process:</strong> Confirmed and posted.</li><li><strong>Paid:</strong> Fully completed.</li></ol><p>Two more statuses appear only when they apply: <strong>Not Paid</strong> and <strong>Cancelled</strong>.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><p>The buttons are in the top bar of the payment page.</p><ul><li><strong>Confirm:</strong> Visible on a <strong>Draft</strong>. Aureus posts the payment and creates its journal entry. The status becomes <strong>In Process</strong>. A payment on a cash journal becomes <strong>Paid</strong>.</li><li><strong>Cancel:</strong> Visible on a <strong>Draft</strong>. The status becomes <strong>Cancelled</strong>.</li><li><strong>Reset to Draft:</strong> Visible once the payment is no longer a draft. The status goes back to <strong>Draft</strong> and the journal entry returns to draft.</li><li><strong>Mark as Sent</strong> and <strong>Unmark as Sent:</strong> Visible on an <strong>In Process</strong> payment with the method <strong>Manual Payment</strong>. Use it to track that you sent the payment details to the partner. The button toggles.</li><li><strong>Delete:</strong> Removes the payment.</li></ul><p>You also find <strong>Chatter</strong> in the top bar. See <a href="./../../getting-started/chatter.html">Chatter</a>.</p><h2 id="the-linked-invoices-or-bills" tabindex="-1">The linked invoices or bills <a class="header-anchor" href="#the-linked-invoices-or-bills" aria-label="Permalink to &quot;The linked invoices or bills&quot;">​</a></h2><p>A payment page has an extra tab: <strong>Invoices</strong> on a customer payment, and <strong>Bills</strong> on a vendor payment. It lists the documents this payment settled. Click <strong>View</strong> to open one. Use it to check which invoice a payment paid.</p><h2 id="the-journal-entry-of-a-payment" tabindex="-1">The journal entry of a payment <a class="header-anchor" href="#the-journal-entry-of-a-payment" aria-label="Permalink to &quot;The journal entry of a payment&quot;">​</a></h2><p>Each confirmed payment has a journal entry. It moves the money between the partner account and the outstanding account. In the Accounting app, open <code>Accounting → Journal Entries</code> and look for the payment number. The entry page has a <strong>Payment</strong> link back to the payment. See <a href="./../accounting-entries/journal-entries.html">Journal entries</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>Deco Addict paid invoice INV/2026/2 for $891.25 through a bank journal.</p><ol><li>Open <code>Customers → Payments</code>. The <strong>In Process</strong> view shows the payment.</li><li>Open it. The type is <strong>Receive</strong>, the method is <strong>Manual Payment</strong>, the amount is $891.25.</li><li>Open the <strong>Invoices</strong> tab. INV/2026/2 is listed.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Do not delete a payment that already settled an invoice. Check the <strong>Invoices</strong> tab first, and keep the records that your accountant needs.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./register-payment.html">Register a payment</a></li><li><a href="./">Payments overview</a></li><li><a href="./bank-accounts.html">Bank accounts</a></li><li><a href="./../accounting-entries/journal-entries.html">Journal entries</a></li></ul>',22))])}const f=o(l,[["render",m]]);export{y as __pageData,f as default};
